def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    grid is a list of lists of integers 0 or 1. Connectivity is 4-directional.
    Returns an integer count.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            x,y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < cols:
                    if not visited[nx][ny] and grid[nx][ny] == 1:
                        stack.append((nx,ny))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i,j)
    return count

