code:
def solve(s: str) -> bool:
    """Return True if s is a valid IPv4 address.
    Rules:
    - Exactly four decimal parts separated by '.'
    - Each part consists of digits only, no leading zeros unless the part is exactly "0"
    - Integer value of each part is between 0 and 255 inclusive
    - No extra whitespace or characters
    """
    if not isinstance(s, str):
        return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p:
            return False
        if not p.isdigit():
            return False
        # leading zeros not allowed unless the part is exactly "0"
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if val < 0 or val > 255:
            return False
    return True

