def solve(weights, values, capacity):
    # Convert capacity to int if possible
    try:
        capacity = int(capacity)
    except Exception:
        return 0
    if capacity <= 0:
        # Still may have zero-weight positive-value items
        extra = 0
        for w, v in zip(weights, values):
            if w == 0 and v > 0:
                extra += v
        return extra
    # Process items
    extra = 0
    items = []  # (weight, value)
    for w, v in zip(weights, values):
        try:
            w = int(w)
            v = int(v)
        except Exception:
            continue
        if w < 0:
            continue
        if w == 0:
            if v > 0:
                extra += v
            continue
        if w > capacity:
            continue
        items.append((w, v))
    dp = [0] * (capacity + 1)
    for w, v in items:
        for c in range(capacity, w - 1, -1):
            new = dp[c - w] + v
            if new > dp[c]:
                dp[c] = new
    return dp[capacity] + extra

