def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting (tails array) for O(n log n).
    Handles empty list.
    """
    import bisect
    if not nums:
        return 0
    tails = []
    for x in nums:
        # find position to replace in tails
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

