def solve(words, k):
    """Return the list of the k most frequent words.
    Words are counted case‑sensitively. Ties are broken by alphabetical order.
    If k is not a positive integer, an empty list is returned.
    Non‑string items in *words* are coerced to strings for counting.
    """
    # Convert k to int safely
    try:
        k = int(k)
    except Exception:
        return []
    if k <= 0:
        return []
    # Count frequencies, coercing non‑strings to str
    freq = {}
    for w in words:
        if not isinstance(w, str):
            w = str(w)
        freq[w] = freq.get(w, 0) + 1
