def solve(s: str) -> str:
    n = len(s)
    if n == 0:
        return ''
    def expand(l: int, r: int):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l+1, r-1
    start = 0
    max_len = 1
    for i in range(n):
        # odd
        l, r = expand(i, i)
        cur_len = r - l + 1
        if cur_len > max_len:
            start, max_len = l, cur_len
        # even
        l, r = expand(i, i+1)
        cur_len = r - l + 1
        if cur_len > max_len:
            start, max_len = l, cur_len
    return s[start:start+max_len]

