def solve(n, edges):
    """Return the lexicographically smallest topological ordering for a directed graph.
    Nodes are 0..n-1. ``edges`` is an iterable of length‑2 sequences [a, b] meaning a → b.
    If the graph contains a cycle, return an empty list.
    The implementation is tolerant of various input types:
    * ``n`` may be any value that can be converted to an int.
    * ``edges`` may be ``None`` or any iterable; invalid edge entries are ignored.
    """
    # Coerce n to int safely
    try:
        n = int(n)
    except Exception:
        return []
    if n <= 0:
        return []
    # Prepare adjacency list and indegree array
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    # Normalize edges to an iterable
    if edges is None:
        edges_iter = []
    else:
        try:
            edges_iter = list(edges)
        except Exception:
            edges_iter = []
    for e in edges_iter:
        # Each edge should be a sequence of two items
        try:
            a, b = e[0], e[1]
        except Exception:
            continue
        # Convert to int if possible
        try:
            a = int(a)
            b = int(b)
        except Exception:
            continue
        if not (0 <= a < n and 0 <= b < n):
            continue
        adj[a].append(b)
        indeg[b] += 1
    # Kahn's algorithm with a min‑heap to get smallest lexical order
    import heapq
    heap = [i for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    # If we couldn't include all nodes, there is a cycle
    if len(order) != n:
        return []
    return order

