def solve(s):
    # Return True if s is a valid IPv4 address according to the specification.
    # Do not modify the input string; leading/trailing spaces make it invalid.
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        # Each part must be non-empty and consist only of digits.
        if not p:
            return False
        if not p.isdigit():
            return False
        # No leading zeros unless the part is exactly "0".
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if val < 0 or val > 255:
            return False
    return True

