def solve(grid):
    if not grid or not grid[0]:
        return 0
    n = len(grid)
    seen = set()
    count = 0
    for i in range(n):
        m = len(grid[i])
        for j in range(m):
            if grid[i][j] == 1 and (i, j) not in seen:
                count += 1
                stack = [(i, j)]
                seen.add((i, j))
                while stack:
                    r, c = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < len(grid[nr]) and grid[nr][nc] == 1 and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
    return count

